def remove_char_at_indices(s, indices):
    idx_set = set(i for i in indices if 0 <= i < len(s))
    return "".join(c for i, c in enumerate(s) if i not in idx_set)

def swap_first_last_char(s):
    if len(s) < 2:
        return s
    chars = list(s)
    chars[0], chars[-1] = chars[-1], chars[0]
    return "".join(chars)

def move_char_to_front(s, ch):
    idx = s.find(ch)
    if idx == -1:
        return s
    return s[idx] + s[:idx] + s[idx + 1:]

def index_of_nth_occurrence(s, ch, n):
    count = 0
    for i, c in enumerate(s):
        if c == ch:
            count += 1
            if count == n:
                return i
    return -1

def replace_nth_occurrence(s, ch, n, replacement):
    count = 0
    for i, c in enumerate(s):
        if c == ch:
            count += 1
            if count == n:
                return s[:i] + replacement + s[i + 1:]
    return s

def distance_between_occurrences(s, ch):
    positions = [i for i, c in enumerate(s) if c == ch]
    return [positions[i + 1] - positions[i] for i in range(len(positions) - 1)]

