def count_case_insensitive_occurrences(s, sub):
    if not sub:
        return 0
    s_l, sub_l = s.lower(), sub.lower()
    count = 0
    start = 0
    while True:
        idx = s_l.find(sub_l, start)
        if idx == -1:
            break
        count += 1
        start = idx + len(sub_l)
    return count

def count_letter_digit_symbol_groups(s):
